import { useState ,useEffect } from "react"

import './networks.css'

import { Header } from '../../components/Header'
import { Input } from '../../components/Input'
import { MdAdd } from 'react-icons/md'


import { db } from '../../services/firebaseConnection'
import {
  doc,
  setDoc,
  getDoc,
} from 'firebase/firestore'

import { toast } from 'react-toastify'


export default function Networks(){

  useEffect(() => {

    function loadLinks(){
     const docRef = doc(db,"social","link")
     getDoc(docRef)
     .then((snapshot) => {

       if(snapshot.data() !== undefined) {
         setFacebook(snapshot.data().facebook)
         setInstagram(snapshot.data().instagram)
         setYoutube(snapshot.data().youtube)
       }

     })

   }

   loadLinks();

 }, [])

  const[facebook,setFacebook] = useState("")
  const[instagram,setInstagram] = useState("")
  const[youtube,setYoutube] = useState("")


  function handleSave(e){
    e.preventDefault();
     setDoc(doc(db,"social","link"),{
      facebook:facebook,
      instagram:instagram,
      youtube:youtube
    })
    .then(() =>{
      console.log("Passou")
      toast.success("Salvo com sucesso")
    })
    .catch((error) =>{
      console.log('Erro ao salvar' + error)
      toast.error('Erro ao salvar o link')
    })
  }
  return(
    <div className='admin-container'>
      <Header/>

      <h1 className='title-social'>Suas redes sociais</h1>

      <form className='form' onSubmit={handleSave}>
        <label className='label'>Link do facebook</label>
        <Input placeholder="Digite a url do facebook..."
        value={facebook}
        onChange={(e) => setFacebook(e.target.value)}
        />

        <label className='label'>Link do Instagram</label>
        <Input placeholder="Digite a url do Instagram..."
        value={instagram}
        onChange={(e) => setInstagram(e.target.value)}/>

        <label className='label'>Link do Youtube</label>
        <Input placeholder="Digite a url do Youtube..."
        value={youtube}
        onChange={(e) => setYoutube(e.target.value)}/>

        <button className='btn-register'>
          Salvar links <MdAdd size={24} color="#FFF"/>
        </button>
      </form>
    </div>
  )
}
